// Verified: this file compiled cleanly with javac 25 against
//   ~/.gradle/caches/fabric-loom/26.2/minecraft-common.jar + minecraft-client-only.jar
// Every symbol below was confirmed by javap/vineflower in this run.
//
// Pipeline order copied from Player.hurtServer -> LivingEntity.hurtServer -> Player.actuallyHurt:
//   difficulty -> (shield) -> armour -> resistance -> enchant protection -> absorption -> health

import net.minecraft.client.Minecraft;
import net.minecraft.client.player.LocalPlayer;
import net.minecraft.core.Holder;
import net.minecraft.core.Registry;
import net.minecraft.core.component.DataComponents;
import net.minecraft.core.registries.Registries;
import net.minecraft.tags.DamageTypeTags;
import net.minecraft.util.Mth;
import net.minecraft.world.Difficulty;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.damagesource.CombatRules;
import net.minecraft.world.damagesource.DamageSource;
import net.minecraft.world.effect.MobEffectInstance;
import net.minecraft.world.effect.MobEffects;
import net.minecraft.world.entity.EquipmentSlot;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.component.DeathProtection;
import net.minecraft.world.item.enchantment.Enchantment;
import net.minecraft.world.item.enchantment.EnchantmentHelper;
import net.minecraft.world.item.enchantment.Enchantments;

public final class BlastEstimate {

    public record Result(float healthLost, float absorptionLost,
                        float finalHealth, boolean lethal, boolean totemSaves) {}

    private static final EquipmentSlot[] ARMOR = {
        EquipmentSlot.HEAD, EquipmentSlot.CHEST, EquipmentSlot.LEGS, EquipmentSlot.FEET
    };

    /** rawDamage = the pre-mitigation explosion damage. Returns null if no local player. */
    public static Result estimate(float rawDamage) {
        Minecraft mc = Minecraft.getInstance();
        LocalPlayer p = mc.player;
        if (p == null || mc.level == null) return null;

        // Real DamageSource, built from the client's synced DAMAGE_TYPE registry.
        // (null, null) -> DamageTypes.EXPLOSION; pass entities for PLAYER_EXPLOSION.
        DamageSource src = mc.level.damageSources().explosion(null, null);

        if (p.getAbilities().invulnerable
                && !src.is(DamageTypeTags.BYPASSES_INVULNERABILITY)) {
            return new Result(0, 0, p.getHealth(), false, false);
        }

        float dmg = rawDamage;

        // 1. difficulty scaling (explosion/player_explosion are scaling = "always")
        if (src.scalesWithDifficulty()) {
            Difficulty d = mc.level.getDifficulty();
            if (d == Difficulty.PEACEFUL)   dmg = 0.0F;
            else if (d == Difficulty.EASY)  dmg = Math.min(dmg / 2.0F + 1.0F, dmg);
            else if (d == Difficulty.HARD)  dmg = dmg * 3.0F / 2.0F;
        }

        // 2. armour (explosion is NOT in bypasses_armor). getWeaponItem() is null for
        //    explosions, so CombatRules' ServerLevel branch is skipped on both sides.
        if (!src.is(DamageTypeTags.BYPASSES_ARMOR)) {
            dmg = CombatRules.getDamageAfterAbsorb(
                p, dmg, src,
                p.getArmorValue(),
                (float) p.getAttributeValue(Attributes.ARMOR_TOUGHNESS));
        }

        // 3. resistance — exact arithmetic from LivingEntity.getDamageAfterMagicAbsorb
        if (!src.is(DamageTypeTags.BYPASSES_EFFECTS)
                && p.hasEffect(MobEffects.RESISTANCE)
                && !src.is(DamageTypeTags.BYPASSES_RESISTANCE)) {
            MobEffectInstance inst = p.getEffect(MobEffects.RESISTANCE);
            if (inst != null) {
                int absorbValue = (inst.getAmplifier() + 1) * 5;
                dmg = Math.max(dmg * (25 - absorbValue) / 25.0F, 0.0F);
            }
        }

        // 4. enchantment protection. EnchantmentHelper.getDamageProtection needs a
        //    ServerLevel, so sum EPF off the worn stacks: Protection +1/level,
        //    Blast Protection +2/level (from the shipped enchantment JSON), then reuse
        //    the vanilla clamp/divider. CombatRules clamps EPF to 20 => max 80% cut.
        if (dmg > 0.0F && !src.is(DamageTypeTags.BYPASSES_ENCHANTMENTS)) {
            Registry<Enchantment> reg =
                mc.level.registryAccess().lookupOrThrow(Registries.ENCHANTMENT);
            Holder<Enchantment> prot  = reg.getOrThrow(Enchantments.PROTECTION);
            Holder<Enchantment> blast = reg.getOrThrow(Enchantments.BLAST_PROTECTION);
            boolean isBlast = src.is(DamageTypeTags.IS_EXPLOSION)
                           && !src.is(DamageTypeTags.BYPASSES_INVULNERABILITY);
            float epf = 0.0F;
            for (EquipmentSlot slot : ARMOR) {
                ItemStack st = p.getItemBySlot(slot);
                epf += EnchantmentHelper.getItemEnchantmentLevel(prot, st) * 1.0F;
                if (isBlast) {
                    epf += EnchantmentHelper.getItemEnchantmentLevel(blast, st) * 2.0F;
                }
            }
            if (epf > 0.0F) dmg = CombatRules.getDamageAfterMagicAbsorb(dmg, epf);
        }

        // 5. absorption soaks first (Player.getAbsorptionAmount is synched data)
        float absorption = p.getAbsorptionAmount();
        float toHealth   = Math.max(dmg - absorption, 0.0F);
        float absorbed   = dmg - toHealth;

        float health      = p.getHealth();
        float finalHealth = Mth.clamp(health - toHealth, 0.0F, p.getMaxHealth());
        boolean lethal    = finalHealth <= 0.0F;

        // 6. totem: DEATH_PROTECTION component in either hand, unless the source
        //    bypasses invulnerability. Item identity is not what vanilla checks.
        boolean totem = false;
        if (lethal && !src.is(DamageTypeTags.BYPASSES_INVULNERABILITY)) {
            for (InteractionHand hand : InteractionHand.values()) {
                DeathProtection dp =
                    p.getItemInHand(hand).get(DataComponents.DEATH_PROTECTION);
                if (dp != null) { totem = true; break; }
            }
        }

        // Caveat: if p.invulnerableTime > 10 the server applies only
        // (dmg - lastHurt), and lastHurt is never synced, so treat the value
        // below as an upper bound in that window.
        return new Result(health - finalHealth, absorbed, finalHealth, lethal, totem);
    }
}
